using FluentValidation;using EventLensAI.Domain.Enums;
namespace EventLensAI.Application.Features.Booth;
public sealed class MediaCaptureRequestValidator:AbstractValidator<MediaCaptureRequest>
{public MediaCaptureRequestValidator(){RuleFor(x=>x.OrganizationId).NotEmpty();RuleFor(x=>x.EventId).NotEmpty();RuleFor(x=>x.SessionId).NotEmpty();RuleFor(x=>x.CaptureMode).IsInEnum();RuleFor(x=>x.FileName).NotEmpty().MaximumLength(255);RuleFor(x=>x.LocalStorageKey).NotEmpty().MaximumLength(500).Must(x=>x.StartsWith("media:")).WithMessage("Only an opaque local media key is accepted.");RuleFor(x=>x.MimeType).Must(x=>new[]{"image/jpeg","image/gif","video/webm","video/mp4","application/vnd.eventlens.live-photo+json"}.Contains(x));RuleFor(x=>x.Width).InclusiveBetween(1,7680);RuleFor(x=>x.Height).InclusiveBetween(1,4320);RuleFor(x=>x.FrameCount).InclusiveBetween(1,600);RuleFor(x=>x.FrameIntervalMs).InclusiveBetween(30,60000);RuleFor(x=>x.DurationSeconds).InclusiveBetween(1,1800);RuleFor(x=>x.Quality).InclusiveBetween(.1m,1m);}}
